using System;using System.IO;using System.Reflection;using System.Threading.Tasks;using System.Windows;using System.Windows.Interop;using CodexStrip;
class TrayDockTest {
 static void Check(StripWindow w){var r=(WorkAreaReservation)typeof(StripWindow).GetField("reservation",BindingFlags.NonPublic|BindingFlags.Instance).GetValue(w);WindowGeometry.RECT actual;WindowGeometry.GetWindowRect(new WindowInteropHelper(w).Handle,out actual);var expected=r.Reserved;if(!r.Active||actual.left!=expected.left||actual.top!=expected.top||actual.right!=expected.right||actual.bottom!=expected.bottom)throw new Exception("visible rectangle differs from reserved edge: "+actual.left+","+actual.top+","+actual.right+","+actual.bottom+" expected "+expected.left+","+expected.top+","+expected.right+","+expected.bottom);var work=WindowGeometry.Bounds(new WindowInteropHelper(w).Handle,true);if(work.right>actual.left)throw new Exception("right work area overlaps bar");}
 [STAThread]static void Main(){Settings.DataDir=Path.GetFullPath("work/tray-dock-test-data");var app=new Application();var w=new StripWindow(true){Width=800,Height=286};TrayHost tray=null;w.Loaded+=async delegate{try{await Task.Delay(100);typeof(StripWindow).GetField("DemoMode").SetValue(w,false);tray=new TrayHost(w);w.Config.ReserveWorkArea=true;w.Config.DockEdge="right";w.Config.DockVerticalSize=320;w.ApplyDockSettings();await Task.Delay(250);Check(w);for(int i=0;i<4;i++){w.HideToTray();await Task.Delay(150);if(w.Docked)throw new Exception("hidden reservation remains");tray.Show();await Task.Delay(300);Check(w);}var hwnd=new WindowInteropHelper(w).Handle;var area=WindowGeometry.Bounds(hwnd,false);WindowGeometry.SetWindowPos(hwnd,IntPtr.Zero,area.left+100,area.top+100,400,700,0x14);await Task.Delay(300);Check(w);w.WindowState=WindowState.Minimized;await Task.Delay(150);tray.Show();await Task.Delay(300);Check(w);w.DockNearest();await Task.Delay(200);Check(w);if(w.Config.DockEdge!="right")throw new Exception("nearest dock action failed");var screen=new WindowGeometry.RECT{left=-1920,top=0,right=0,bottom=1080};if(WindowGeometry.NearestEdge(new WindowGeometry.RECT{left=-1900,top=100,right=-1580,bottom=900},screen,true)!="left"||WindowGeometry.NearestEdge(new WindowGeometry.RECT{left=-340,top=100,right=-20,bottom=900},screen,true)!="right"||WindowGeometry.NearestEdge(new WindowGeometry.RECT{left=-1800,top=20,right=-200,bottom=260},screen,false)!="top"||WindowGeometry.NearestEdge(new WindowGeometry.RECT{left=-1800,top=800,right=-200,bottom=1040},screen,false)!="bottom")throw new Exception("nearest edge selection failed");var button=(System.Windows.Controls.Button)typeof(StripWindow).GetField("dockButton",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);if(!button.ToolTip.ToString().Contains("已停靠右侧"))throw new Exception("active hint missing");w.SetTheme("light");w.Snapshot("work/dock-toggle-light.png");w.SetTheme("dark");w.Snapshot("work/dock-toggle-dark.png");w.ToggleDock();await Task.Delay(200);button=(System.Windows.Controls.Button)typeof(StripWindow).GetField("dockButton",BindingFlags.Instance|BindingFlags.NonPublic).GetValue(w);if(w.Docked||button.ToolTip.ToString().Contains("已停靠"))throw new Exception("toggle to floating failed");w.UpdateDockButton();if(!button.ToolTip.ToString().Contains("停靠到"))throw new Exception("floating direction missing");w.ToggleDock();await Task.Delay(250);Check(w);File.WriteAllText("work/tray-dock-test.txt","PASS: toggle dock/floating and active/directional hints; nearest four-edge selection and actual dock button action; real StripWindow/TrayHost right docking, four hide/show cycles, stale-position repair, minimize/show, native window matches reserved work area");}catch(Exception e){File.WriteAllText("work/tray-dock-test.txt",e.ToString());}finally{if(tray!=null)tray.Exit();else w.Close();}};app.Run(w);}
}

